examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true })
if (open) {
    MonarchDialog(
        onDismissRequest = {},
        title = "We’ve updated our terms",
        description = "Effective from $effective",
        dismissible = false,
        actions = {
            MonarchButton(text = {{declineLabel}}, onClick = { open = false }, size = MonarchButtonSize.Sm)
            MonarchButton(
                text = "Accept and continue",
                onClick = { open = false },
                variant = MonarchButtonVariant.Primary,
                size = MonarchButtonSize.Sm,
            )
        },
    ) {
        Column(
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        ) {
            MonarchText(text = {{summary.intro}})
            MonarchText(text = "• " + {{summary.items.0}})
            MonarchText(text = "• " + {{summary.items.1}})
            MonarchText(text = "Read the full documents", style = MonarchTextStyle.Label)
            MonarchLink(text = {{documents.0.label}} + " (version " + {{documents.0.version}} + ")", onClick = {}, variant = MonarchLinkVariant.Standalone)
            MonarchLink(text = {{documents.1.label}} + " (version " + {{documents.1.version}} + ")", onClick = {}, variant = MonarchLinkVariant.Standalone)
        }
    }
}

examples.setupTemplate:
var open by remember { mutableStateOf(true) }
val effective = remember {
    android.icu.text.DateFormat.getDateInstance(android.icu.text.DateFormat.LONG, java.util.Locale.forLanguageTag({{locale}}))
        .apply { timeZone = android.icu.util.TimeZone.getTimeZone("UTC") }
        .format(java.util.Date({{effectiveDate|millis}}))
}

