if (open) {
    MonarchDialog(
        onDismissRequest = {},
        title = "We’ve updated our terms",
        description = "Effective from $effective",
        dismissible = false,
        actions = {
            MonarchButton(text = "Sign out", onClick = { open = false }, size = MonarchButtonSize.Sm)
            MonarchButton(
                text = "Accept and continue",
                onClick = { open = false },
                variant = MonarchButtonVariant.Primary,
                size = MonarchButtonSize.Sm,
            )
        },
    ) {
        Column(
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        ) {
            MonarchText(text = "Here is what changed:")
            MonarchText(text = "• " + "We explain how long we keep support messages.")
            MonarchText(text = "• " + "We list the providers that host your data.")
            MonarchText(text = "Read the full documents", style = MonarchTextStyle.Label)
            MonarchLink(text = "Terms of Service" + " (version " + "2026-12-01" + ")", onClick = {}, variant = MonarchLinkVariant.Standalone)
            MonarchLink(text = "Privacy Policy" + " (version " + "2026-12-01" + ")", onClick = {}, variant = MonarchLinkVariant.Standalone)
        }
    }
}
